# Custom (non-formula-framework) calculators added 2026-11-04. Each entry: custom=(form_html, js), faq=[(q,a)...]
import math as _m
def _fld(i,us,mt=None,val='',mv=None,k=None,cls='',extra=''):
    lab=us if mt is None else f"<span class='us'>{us}</span><span class='mt'>{mt}</span>"
    a=(f" data-k='{k}'" if k else '')+(f" data-mv='{mv}'" if mv is not None else '')
    return f"<div class='f{(' '+cls) if cls else ''}'{extra}><label for='{i}'>{lab}</label><input id='{i}' type='text' inputmode='decimal' autocomplete='off' spellcheck='false' value='{val}'{a} aria-describedby='{i}-e'><span class='fe' id='{i}-e'></span></div>"
def _sel(i,lab,opts,cls='',extra=''):
    return f"<div class='f{(' '+cls) if cls else ''}'{extra}><label for='{i}'>{lab}</label><select id='{i}'>"+"".join(f"<option value='{v}'>{t}</option>" for v,t in opts)+"</select></div>"
def _chk(i,lab,on=False):
    return f"<div class='f fw ck'><label><input type='checkbox' id='{i}'{' checked' if on else ''}> {lab}</label></div>"
UNITS=CJ.build("x",dict(f=[("L","Length (ft)",1)],js="return [];"))[1]
PM4CSS=".calc .fw,.calc .its,.calc .itb,.calc .wr{grid-column:1/-1}.calc select{width:100%;min-height:44px;font:inherit;border:1px solid #cbd5e1;border-radius:10px;padding:8px;background:#fff;max-width:100%}.its{display:grid;gap:12px;min-width:0}.it{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;border:1px solid #e2e8f0;border-radius:12px;padding:10px;min-width:0}.it .f{min-width:0}.itn{font-weight:700;color:#0f766e;grid-column:1/-1}.iu{display:flex;gap:6px;min-width:0}.iu input{flex:1 1 auto;min-width:0;width:100%}.iu select{flex:0 0 72px;width:72px}.it.cyl .d-l,.it.cyl .d-w,.it:not(.cyl) .d-d{display:none}.rm,.add{font:inherit;border:1px solid #cbd5e1;background:#fff;border-radius:10px;padding:8px 12px;cursor:pointer;min-height:40px}.rm:disabled{opacity:.4;cursor:default}.ck label{display:flex;gap:8px;align-items:center;font-weight:500}.warn{background:#fffbeb;border:1px solid #f59e0b;color:#78350f;border-radius:10px;padding:10px;margin:10px 0 0;overflow-wrap:anywhere}.pt{border-collapse:collapse;width:100%;font-size:.95em}.pt th,.pt td{border-bottom:1px solid #e2e8f0;padding:6px;text-align:left}.calc [hidden]{display:none!important}.guide{overflow-wrap:anywhere}"
def _js(k): return open(f"pm4/{k}.js").read()
_CUBE_TPL=("<div id='itpl' hidden><div class='it'><span class='itn'></span>"
 "<div class='f'><label data-f='sh'>Shape</label><select class='sh' data-i='sh'><option value='b'>Box (length × width × height)</option><option value='c'>Cylinder (diameter × height)</option></select></div>"
 "<div class='f'><label data-f='q'>Quantity</label><input class='q' data-i='q' type='text' inputmode='decimal' autocomplete='off' value='1'><span class='fe' data-e='q'></span></div>"
 +"".join(f"<div class='f dim d-{c}'><label data-f='{c}'>{l}</label><span class='iu'><input data-i='{c}' type='text' inputmode='decimal' autocomplete='off' spellcheck='false' value='{v}' data-mv='{mv}'><select data-i='{c}u' aria-label='Unit'><option value='ft'>ft</option><option value='in'>in</option><option value='yd'>yd</option><option value='m'>m</option><option value='cm'>cm</option></select></span><span class='fe' data-e='{c}'></span></div>" for c,l,v,mv in [("l","Length",4,1.2),("w","Width",3,0.9),("d","Diameter",2,0.6),("h","Height",2,0.6)])
 +"<button type='button' class='rm'>Remove item</button></div></div>")
def _pt():
    r="".join(f"<tr><td>{p}/12</td><td>{_m.degrees(_m.atan(p/12)):.2f}°</td><td>{p/12*100:.1f} %</td><td>{_m.sqrt(1+(p/12)**2):.3f}</td></tr>" for p in range(3,13))
    return "<table class='pt'><thead><tr><th>Pitch</th><th>Angle</th><th>Slope</th><th>Multiplier</th></tr></thead><tbody>"+r+"</tbody></table>"
T4={
"cubic-feet-calculator":dict(cat="Interior",t="Cubic Feet Calculator – Volume of Boxes, Rooms & Cylinders",d="Cubic feet calculator: add boxes or cylinders in mixed units and get the total volume in cubic feet, cubic yards, cubic meters, liters and gallons.",h="Cubic Feet Calculator",
custom=("<div class='its fw' id='items'></div>"+_CUBE_TPL+"<div class='itb'><button type='button' class='add' id='add'>+ Add item</button></div>",_js("cubic-feet-calculator")),
g="<h2>How to use the cubic feet calculator</h2><ol><li>Choose a shape for each item: a box (length × width × height) or a cylinder (diameter × height).</li><li>Type each measurement and pick its unit. You can mix feet, inches, yards, meters and centimeters.</li><li>Set the quantity, then add more items if needed. The total updates as you type.</li></ol><h2>Formula</h2><p>Box: volume = length × width × height. Cylinder: volume = π × (diameter ÷ 2)² × height. Convert every measurement to feet first: 1 in = 1/12 ft, 1 yd = 3 ft, 1 m = 3.2808 ft.</p><p>1 ft³ = 1,728 in³ = 0.037037 yd³ = 0.0283168 m³ = 28.3168 L = 7.48052 US gal.</p><p><b>Example:</b> a box 4 ft × 3 ft × 2 ft = 24 ft³ = 0.889 yd³ = 0.68 m³ (679.6 L). A box 24 × 18 × 12 in = 5,184 in³ = 3 ft³.</p><h2>Tips</h2><ul><li>Measure inside dimensions for storage, moving boxes or planters.</li><li>Divide cubic feet by 27 to get cubic yards for soil, mulch or concrete orders.</li><li>For an L-shaped room, split it into two boxes and add them.</li></ul>",
faq=[("How do I calculate cubic feet?","Multiply length × width × height with all three in feet. If you measured in inches, multiply the inches and divide by 1,728."),("How many cubic feet are in a cubic yard?","27, because a cubic yard is 3 ft × 3 ft × 3 ft."),("How do I convert cubic feet to cubic meters?","Multiply by 0.0283168. For example, <span class='nocv'>24 ft³</span> × 0.0283168 = 0.68 m³."),("Can I mix inches and feet?","Yes. Each measurement has its own unit menu and the calculator converts everything before multiplying."),("How do I find the volume of a round container?","Choose Cylinder and enter the inside diameter and height. The calculator uses π × radius² × height.")]),
"voltage-drop-calculator":dict(cat="Interior",t="Voltage Drop Calculator – Wire Size by AWG or mm²",d="Voltage drop calculator: enter voltage, current, one-way length and copper or aluminum wire to get the drop, percent and the smallest size that stays within 3 percent.",h="Voltage Drop Calculator",
custom=(UNITS+_sel("vs","Supply voltage",[(x,f"{x} V") for x in ("120","208","230","240","277","400","480","12","24","48")]+[("c","Custom…")])+_fld("vc","Custom voltage (V)",val="120",extra=" id='vcw' hidden")+_sel("ph","System",[("1","Single-phase AC"),("3","Three-phase AC"),("dc","DC")])+_sel("cd","Conductor",[("cu","Copper"),("al","Aluminum")])+"<div class='f'><label for='ws'>Wire size</label><select id='ws'></select></div>"+_fld("L","One-way length (ft)","One-way length (m)",100,30,0.3048)+_fld("I","Load current (A)",val=16),_js("voltage-drop-calculator")),
g="<h2>How to use the voltage drop calculator</h2><ol><li>Pick the supply voltage and the system: single-phase AC, three-phase AC or DC.</li><li>Choose copper or aluminum and the wire size (AWG/kcmil in US mode, mm² in metric mode).</li><li>Enter the one-way length from the panel to the load and the load current in amps.</li></ol><h2>Formula</h2><p>US: VD = 2 × K × I × L ÷ CM for single-phase or DC, and 1.732 × K × I × L ÷ CM for three-phase. K = 12.9 for copper and 21.2 for aluminum; CM is the wire area in circular mils; L is the one-way length in feet.</p><p>Metric: VD = 2 × ρ × L × I ÷ A (1.732 for three-phase), with ρ = 0.0172 Ω·mm²/m for copper and 0.0282 for aluminum at 20 °C and A in mm².</p><p><b>Example:</b> 120 V, copper, 12 AWG (6,530 CM), 100 ft, 16 A: VD = 2 × 12.9 × 16 × 100 ÷ 6,530 = 6.32 V, which is 5.27 %. 8 AWG is the smallest size within 3 %.</p><h2>Tips</h2><ul><li>3 % for a branch circuit and 5 % for feeder plus branch are recommendations (<span class='nod'>NEC 210.19(A)</span> Informational Note), not code requirements.</li><li>Real conductors run warmer than 20 °C, so actual drop is slightly higher.</li><li>Voltage drop is not the same as ampacity: the wire must also be rated for the current. Have a licensed electrician confirm the final size.</li></ul>",
faq=[("What is an acceptable voltage drop?","A common recommendation is at most 3 % on a branch circuit and 5 % total for feeder plus branch circuit."),("Is the 3 % rule a code requirement?","No. In the NEC it is an Informational Note, a recommendation. Local rules may differ, so check with your electrician or inspector."),("Should I use one-way or round-trip length?","Enter the one-way length. The formula already doubles it for the return conductor."),("Why does aluminum need a bigger wire?","Aluminum has about 64 % higher resistance than copper, so it needs a larger cross-section for the same drop."),("Does this calculator size wire for ampacity?","No. It only checks voltage drop. The wire must also meet ampacity, temperature and breaker rules. This is not a substitute for a licensed electrician.")]),
"concrete-slab-cost-calculator":dict(cat="Concrete & masonry",t="Concrete Slab Cost Calculator – Bags vs Ready-Mix",d="Concrete slab cost calculator: slab size and thickness to volume with waste, bags needed and the cost of bags versus a ready-mix truck using your local prices.",h="Concrete Slab Cost Calculator",
custom=(UNITS+_fld("L","Slab length (ft)","Slab length (m)",10,3,0.3048)+_fld("W","Slab width (ft)","Slab width (m)",10,3,0.3048)+_fld("T","Thickness (in)","Thickness (cm)",4,10,2.54)+_fld("X","Waste (%)",val=10)
 +"<p class='fw nt'>Prices: enter what your local store charges (optional).</p>"+_fld("P80","Price per 80 lb bag","Price per 36 kg bag")+_fld("P60","Price per 60 lb bag","Price per 27 kg bag")+_fld("P40","Price per 40 lb bag","Price per 18 kg bag")+_fld("PR","Ready-mix price per yd³","Ready-mix price per m³",k=1.30795)+_fld("DF","Delivery fee")+_fld("GD","Gravel base depth (in)","Gravel base depth (cm)",k=2.54)+_fld("GP","Gravel price per yd³","Gravel price per m³",k=1.30795)+_fld("MP","Wire mesh price per ft²","Wire mesh price per m²",k=10.7639),_js("concrete-slab-cost-calculator")),
g="<h2>How to use the slab cost calculator</h2><ol><li>Enter slab length, width and thickness and a waste allowance (10 % is typical).</li><li>Type the prices from your local store or supplier. Leave a price blank if you do not know it.</li><li>Compare the cost of bags with a ready-mix truck. Gravel base and wire mesh are added to every option.</li></ol><h2>Formula</h2><p>Volume = length × width × thickness, plus waste. Bags = volume ÷ bag yield, rounded up. Yields (Quikrete): 80 lb ≈ 0.60 ft³, 60 lb ≈ 0.45 ft³, 40 lb ≈ 0.30 ft³.</p><p><b>Example:</b> 10 ft × 10 ft × 4 in with 10 % waste = 36.67 ft³ = 1.36 yd³, which is 62 bags of 80 lb.</p><h2>Tips</h2><ul><li>Above about 1 yd³, a ready-mix truck is usually easier than mixing dozens of bags; ask about short-load fees.</li><li>Use 4 in for patios and walks and 5–6 in for driveways or heavy loads.</li><li>Prices vary widely by region, so this calculator never fills them in for you.</li></ul>",
faq=[("How many bags of concrete for a 10 × 10 slab?","At 4 in thick with 10 % waste you need about 62 bags of 80 lb, 82 bags of 60 lb or 123 bags of 40 lb."),("When is ready-mix cheaper than bags?","Usually above about 1 to 1.5 yd³, but it depends on your local bag price, ready-mix price and delivery fee. Enter them to compare."),("Why are the prices empty?","Concrete prices change by region and season. Enter your own prices so the comparison is accurate."),("Do I need a gravel base?","Most slabs sit on 4 in of compacted gravel for drainage and support. Enter the depth and price to include it."),("Does the cost include tools and labor?","No. It covers concrete, gravel and mesh only. Add forms, rebar, tool rental and labor separately.")]),
"roof-pitch-calculator":dict(cat="Outdoor & yard",t="Roof Pitch Calculator – Pitch, Angle & Rafter Length",d="Roof pitch calculator: rise and run, angle or span to pitch in x/12, degrees, slope percent, pitch multiplier and rafter length with overhang.",h="Roof Pitch Calculator",
custom=(UNITS+_sel("md","Calculate from",[("rr","Rise and run"),("an","Roof angle"),("sp","Span and pitch (rafter length)")],cls='fw')+_fld("R","Rise",val=6,extra=" data-m='rr'")+_fld("Rn","Run (same unit as rise)",val=12,extra=" data-m='rr'")+_fld("A","Roof angle (°)",val="26.57",extra=" data-m='an'")+_fld("S","Building span (ft)","Building span (m)",24,7.2,0.3048,extra=" data-m='sp'")+_fld("P","Pitch (rise per 12)",val=6,extra=" data-m='sp' data-uu='0'")+_fld("PA","Roof angle (°)",val="26.57",extra=" data-m='sp' data-uu='1'")+_fld("O","Overhang, horizontal (in)","Overhang, horizontal (cm)",12,30,2.54,extra=" data-m='sp'"),_js("roof-pitch-calculator")),
g="<h2>How to use the roof pitch calculator</h2><ol><li>Choose what you know: rise and run, the roof angle, or the building span with the pitch.</li><li>Enter the values. Rise and run can be in any unit as long as both use the same one.</li><li>For rafters, add the horizontal overhang. The rafter length includes the overhang along the slope.</li></ol><h2>Formula</h2><p>Pitch = rise ÷ run × 12 (written x/12). Angle = arctan(rise ÷ run). Slope % = rise ÷ run × 100. Pitch multiplier = √(1 + (rise ÷ run)²). Rafter = (span ÷ 2) × multiplier + overhang × multiplier.</p><p><b>Example:</b> a 6/12 roof has an angle of 26.57°, a slope of 50 % and a multiplier of 1.118. With a 24 ft span and 12 in overhang the rafter is 12 × 1.118 + 1 × 1.118 = 14.53 ft.</p><h2>Common pitches</h2>"+_pt()+"<h2>Tips</h2><ul><li>Most asphalt shingles need at least 2/12 (with extra underlayment) and normally 4/12 or steeper.</li><li>Rafter length here is measured along the top edge to the plumb cut; adjust for ridge board thickness.</li><li>Multiply the plan area of the roof by the pitch multiplier to get the actual roof surface area.</li></ul>",
faq=[("What does 6/12 pitch mean?","The roof rises 6 units for every 12 units of horizontal run, which is an angle of 26.57°."),("How do I convert pitch to degrees?","Angle = arctan(pitch ÷ 12). For 4/12 that is arctan(0.333) = 18.43°."),("What is the pitch multiplier?","The factor that turns horizontal distance into length along the slope: √(1 + (pitch ÷ 12)²). For 6/12 it is 1.118."),("What is a flat roof pitch?","A 0° angle is 0/12. Low-slope roofs below about 2/12 need membrane roofing instead of shingles."),("Can I measure pitch from inside the attic?","Yes. Hold a level 12 in long against a rafter and measure straight up from the level to the rafter. That measurement is the rise per 12.")]),
"retaining-wall-calculator":dict(cat="Outdoor & yard",t="Retaining Wall Calculator – Blocks, Caps & Gravel",d="Retaining wall block calculator: wall length and height to courses, blocks with waste, cap blocks, gravel backfill and drain pipe.",h="Retaining Wall Calculator",
custom=(UNITS+_fld("L","Wall length (ft)","Wall length (m)",20,6,0.3048)+_fld("H","Exposed wall height (ft)","Exposed wall height (m)",3,"0.9",0.3048)+"<div class='f fw'><label for='bp'>Block size</label><select id='bp'><option value='12,4,300,100'>12 × 4 in / 300 × 100 mm</option><option value='18,6,450,150'>18 × 6 in / 450 × 150 mm</option><option value='16,8,400,200'>16 × 8 in / 400 × 200 mm</option><option value=''>Custom</option></select></div>"+_fld("BL","Block face length (in)","Block face length (mm)",12,300,25.4)+_fld("BH","Block face height (in)","Block face height (mm)",4,100,25.4)+_fld("CL","Cap block length (in)","Cap block length (mm)",12,300,25.4)+_fld("GD","Gravel backfill depth behind wall (in)","Gravel backfill depth behind wall (cm)",12,30,2.54)+_fld("X","Waste (%)",val=5)+_chk("bu","Bury the first course (adds one course)")+_chk("dr","Include perforated drain pipe",True),_js("retaining-wall-calculator")),
g="<h2>How to use the retaining wall calculator</h2><ol><li>Enter the wall length and the exposed height above the finished grade.</li><li>Pick a block size or type the face length and height from the block label, plus the cap length.</li><li>Tick the box if the first course is buried, and set the gravel depth behind the wall.</li></ol><h2>Formula</h2><p>Courses = height ÷ block height, rounded up (+1 if the first course is buried). Blocks per course = length ÷ block length, rounded up. Blocks = courses × blocks per course, then waste is added. Caps = length ÷ cap length. Gravel = length × height × depth, at about 1.4 tons per yd³ (≈1.66 t/m³).</p><p><b>Example:</b> 20 ft × 3 ft with 12 × 4 in blocks = 9 courses × 20 blocks = 180 blocks before waste, 189 with 5 % waste, plus 20 caps.</p><h2>Tips</h2><ul><li>Walls taller than 4 ft (1.2 m), or walls holding back a slope, driveway or building, need an engineered design under <span class='nod'>IRC R404.4</span> and often a permit.</li><li>Use clean angular gravel behind the wall and a perforated drain pipe at the base with an outlet.</li><li>Gravel density varies by stone; ask your supplier for their figure.</li></ul>",
faq=[("How many blocks do I need for a retaining wall?","Divide the height by the block height for courses and the length by the block length for blocks per course, then multiply and add 5 % waste."),("Should the first course be buried?","Most manufacturers recommend burying the base course, often about 1 in per 8 in of wall height, with at least one full block."),("When does a retaining wall need an engineer?","Under <span class='nod'>IRC R404.4</span>, walls retaining more than 4 ft (1.2 m) of unbalanced fill need an engineered design. Local rules can be stricter."),("How much gravel goes behind a retaining wall?","Typically a 12 in (30 cm) zone of drainage gravel for the full height. The calculator multiplies length × height × depth."),("Do I need a drain pipe?","Yes, for most walls. A perforated pipe at the base lets water escape so pressure does not build up behind the wall.")]),
}
